// =====================================================
// ORIGINAL EMAIL
// =====================================================

const email = $('Get a message').first().json;


// =====================================================
// EMAIL INFORMATION
// =====================================================

const body =
  email.text ||
  email.html ||
  '';

const senderAddress =
  email.from?.value?.[0]?.address ||
  email.from?.email ||
  'Unknown sender';

const subject =
  email.subject ||
  '';


// =====================================================
// GET ALL PROCESSED ATTACHMENTS FROM MERGE
// =====================================================

const inputItems = $input.all();


// =====================================================
// REMOVE DUPLICATES
// =====================================================

const attachmentMap = new Map();

for (const item of inputItems) {

  const data = item.json || {};

  // Only process actual attachment records
  if (!data.attachmentId && !data.fileName) {
    continue;
  }

  const attachmentId =
    data.attachmentId ||
    data.fileName ||
    `attachment_${attachmentMap.size}`;


  const currentText =
    data.extractedText ||
    '';


  const existing =
    attachmentMap.get(attachmentId);


  // ---------------------------------------------------
  // FIRST VERSION OF ATTACHMENT
  // ---------------------------------------------------

  if (!existing) {

    attachmentMap.set(
      attachmentId,
      {
        attachmentId,

        fileName:
          data.fileName ||
          'Unknown attachment',

        mimeType:
          data.mimeType ||
          null,

        fileType:
          data.fileType ||
          'unknown',

        extractedText:
          currentText,

        extractionSuccessful:
          data.extractionSuccessful === true,

        needsOCR:
          data.needsOCR === true,

        extractionMethod:
          data.extractionMethod ||
          'unknown',

        validationStatus:
          data.validationStatus ||
          null,

        isInvoice:
          data.isInvoice ??
          null
      }
    );

  }


  // ---------------------------------------------------
  // DUPLICATE ATTACHMENT
  // Keep the version with the most text
  // ---------------------------------------------------

  else if (
    currentText.length >
    (existing.extractedText || '').length
  ) {

    existing.extractedText =
      currentText;

    existing.extractionSuccessful =
      data.extractionSuccessful === true;

    existing.needsOCR =
      data.needsOCR === true;

    existing.extractionMethod =
      data.extractionMethod ||
      existing.extractionMethod;

    existing.validationStatus =
      data.validationStatus ||
      existing.validationStatus;

    existing.isInvoice =
      data.isInvoice ??
      existing.isInvoice;
  }
}


// =====================================================
// CONVERT TO ARRAY
// =====================================================

const attachments =
  Array.from(
    attachmentMap.values()
  );


// =====================================================
// BUILD ATTACHMENT TEXT
// =====================================================

const attachmentSections =
  attachments.map(
    (attachment, index) => {

      const status =
        attachment.extractionSuccessful
          ? 'Text extracted successfully'
          : attachment.needsOCR
            ? 'OCR required'
            : 'No usable text extracted';


      return [
        `ATTACHMENT ${index + 1}`,
        `Attachment ID: ${attachment.attachmentId}`,
        `File name: ${attachment.fileName}`,
        `MIME type: ${attachment.mimeType || 'Unknown'}`,
        `File type: ${attachment.fileType}`,
        `Processing status: ${status}`,
        `Extraction method: ${attachment.extractionMethod}`,
        '',
        'CONTENT:',
        attachment.extractedText ||
          '[No text extracted]'
      ].join('\n');

    }
  );


// =====================================================
// BUILD FINAL MESSAGE
// =====================================================

const messageParts = [];


// EMAIL INFORMATION

messageParts.push(
  [
    'EMAIL INFORMATION',
    `Sender: ${senderAddress}`,
    subject
      ? `Subject: ${subject}`
      : ''
  ]
  .filter(Boolean)
  .join('\n')
);


// EMAIL BODY

if (body && body.trim()) {

  messageParts.push(
    `EMAIL BODY:\n${body.trim()}`
  );

}


// ATTACHMENTS

if (attachmentSections.length > 0) {

  messageParts.push(
    `ATTACHMENTS:\n\n${
      attachmentSections.join(
        '\n\n========================================\n\n'
      )
    }`
  );

}


// =====================================================
// FINAL OUTPUT — ONE ITEM
// =====================================================

return [
  {
    json: {

      message:
        messageParts.join(
          '\n\n========================================\n\n'
        ),

      email: {
        sender: senderAddress,
        subject,
        body
      },

      attachmentCount:
        attachments.length,

      attachments

    }
  }
];

// ============================================================
// 1. GET CLAUDE RESPONSE
// ============================================================

const rawResponse = $json.content?.[0]?.text || '';

if (!rawResponse.trim()) {
  throw new Error("Claude returned an empty response");
}


// ============================================================
// 2. PARSE CLAUDE JSON
// ============================================================

let data;

try {
  // First attempt: Claude returned clean JSON
  data = JSON.parse(rawResponse);
} catch (error) {

  // Claude sometimes wraps JSON in ```json ... ```
  const cleaned = rawResponse
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  try {
    data = JSON.parse(cleaned);
  } catch (error) {
    throw new Error(
      `Claude did not return valid JSON. Response: ${rawResponse}`
    );
  }
}


// Make sure Claude returned an object
if (
  typeof data !== 'object' ||
  data === null ||
  Array.isArray(data)
) {
  throw new Error("Claude response is not a valid JSON object");
}


const errors = [];


// ============================================================
// HELPERS
// ============================================================

function isBlank(value) {
  return (
    value === undefined ||
    value === null ||
    String(value).trim() === ''
  );
}

function cleanString(value) {
  if (isBlank(value)) return '';
  return String(value).trim();
}


// ============================================================
// IS INVOICE
// ============================================================

const isInvoice = data["is_invoice"];

if (typeof isInvoice !== "boolean") {
  errors.push("is_invoice must be true or false");
}


// ============================================================
// REQUIRED FIELDS
// ============================================================

const vendorName = cleanString(data["vendor name"]);
const invoiceNumber = cleanString(data["invoice number"]);
const currency = cleanString(data["currency"]).toUpperCase();
const invoiceDate = cleanString(data["invoice date"]);
const dueDate = cleanString(data["due date"]);

if (!vendorName) {
  errors.push("Missing vendor name");
}

if (!invoiceNumber) {
  errors.push("Missing invoice number");
}

if (!currency) {
  errors.push("Missing currency");
}

if (!invoiceDate) {
  errors.push("Missing invoice date");
}


// ============================================================
// EMAIL
// ============================================================

const senderEmail = cleanString(
  data["sender email"]
).toLowerCase();

if (
  senderEmail &&
  !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(senderEmail)
) {
  errors.push("Invalid sender email");
}


// ============================================================
// CURRENCY
// ============================================================

if (currency && !/^[A-Z]{3}$/.test(currency)) {
  errors.push(`Invalid currency format: ${currency}`);
}


// ============================================================
// DATES
// ============================================================

function isValidDate(value) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) {
    return false;
  }

  const date = new Date(`${value}T00:00:00Z`);

  return (
    !isNaN(date.getTime()) &&
    date.toISOString().slice(0, 10) === value
  );
}

if (invoiceDate && !isValidDate(invoiceDate)) {
  errors.push(`Invalid invoice date: ${invoiceDate}`);
}

if (dueDate && !isValidDate(dueDate)) {
  errors.push(`Invalid due date: ${dueDate}`);
}


// ============================================================
// DATE LOGIC
// ============================================================

// A due date should normally not be before the invoice date.

if (
  invoiceDate &&
  dueDate &&
  isValidDate(invoiceDate) &&
  isValidDate(dueDate)
) {
  const invoice = new Date(`${invoiceDate}T00:00:00Z`);
  const due = new Date(`${dueDate}T00:00:00Z`);

  if (due < invoice) {
    errors.push(
      `Due date (${dueDate}) is earlier than invoice date (${invoiceDate})`
    );
  }
}


// ============================================================
// TOTAL AMOUNT
// ============================================================

let totalAmount = data["total amount"];

if (typeof totalAmount === "string") {
  totalAmount = totalAmount
    .replace(/,/g, "")
    .replace(/[€£$]/g, "")
    .trim();
}

if (
  totalAmount === "" ||
  totalAmount === null ||
  totalAmount === undefined
) {
  errors.push("Missing total amount");
} else {

  totalAmount = Number(totalAmount);

  if (!Number.isFinite(totalAmount)) {
    errors.push("Total amount is not a valid number");
  } else if (totalAmount < 0) {
    errors.push("Total amount cannot be negative");
  }
}

// ============================================================
// INVOICE ID
// ============================================================

const invoiceId = [
  vendorName
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, ""),
  totalAmount,
  invoiceDate
]
  .filter(value => !isBlank(value))
  .join("-");



// ============================================================
// INVOICE DESCRIPTION
// ============================================================

const invoiceDescription = cleanString(
  data["invoice description"]
);


// ============================================================
// SOURCE TYPE
// ============================================================

const validSourceTypes = [
  "pdf_attachment",
  "email_body"
];

const sourceType = cleanString(
  data["source type"]
);

if (
  sourceType &&
  !validSourceTypes.includes(sourceType)
) {
  errors.push(`Invalid source type: ${sourceType}`);
}


// ============================================================
// FILE URL
// ============================================================

const fileUrl = cleanString(
  data["file url"]
);

if (fileUrl) {
  try {
    new URL(fileUrl);
  } catch {
    errors.push("Invalid file URL");
  }
}


// ============================================================
// FINAL OUTPUT
// ============================================================

return [
  {
    json: {

      // Clean invoice data
      "invoice ID": invoiceId,
      "is_invoice": isInvoice,
      "vendor name": vendorName,
      "sender email": senderEmail,
      "invoice number": invoiceNumber,
      "invoice date": invoiceDate,
      "due date": dueDate,
      "total amount": totalAmount,
      "currency": currency,
      "invoice description": invoiceDescription,
      "source type": sourceType,
      "file url": fileUrl,

      // Validation
      valid: errors.length === 0,

      validation_status:
        errors.length === 0
          ? "valid"
          : "invalid",

      validation_errors:
        errors.length === 0
          ? ""
          : errors.join("; ")
    }
  }
];

const output = [];

for (const item of $input.all()) {

  if (!item.binary) continue;

  for (const [key, binaryData] of Object.entries(item.binary)) {

    output.push({
      json: {
        attachmentId: key,

        fileName: binaryData.fileName || key,

        mimeType: binaryData.mimeType || null,

        fileType: null,

        extractedText: '',

        extractionSuccessful: false,

        needsOCR: false,

        extractionMethod: null,
      },

      binary: {
        data: binaryData
      }
    });
  }
}

return output;

const text = ($json.extractedText || '').trim();

const lowerText = text.toLowerCase();


// --------------------------------------------------
// Invoice signal groups
// --------------------------------------------------

const invoiceNumberSignals = [
  'invoice number',
  'invoice no',
  'invoice #',
  'invoice:',
  'inv-',
  'inv '
];

const vendorSignals = [
  'vendor',
  'supplier',
  'seller',
  'from:',
  'billed by',
  'bill from'
];

const totalSignals = [
  'total',
  'total amount',
  'amount due',
  'balance due',
  'grand total'
];

const dateSignals = [
  'invoice date',
  'date:',
  'due date',
  'issue date'
];

const billingSignals = [
  'bill to',
  'billed to',
  'customer',
  'client'
];


// --------------------------------------------------
// Helper
// --------------------------------------------------

function hasSignal(signals) {
  return signals.some(signal =>
    lowerText.includes(signal)
  );
}


// --------------------------------------------------
// Detect fields
// --------------------------------------------------

const hasInvoiceNumber =
  hasSignal(invoiceNumberSignals);

const hasVendor =
  hasSignal(vendorSignals);

const hasTotal =
  hasSignal(totalSignals);

const hasDate =
  hasSignal(dateSignals);

const hasBillingInformation =
  hasSignal(billingSignals);


// --------------------------------------------------
// Count invoice fields
// --------------------------------------------------

const detectedFields = [];

if (hasInvoiceNumber)
  detectedFields.push('invoiceNumber');

if (hasVendor)
  detectedFields.push('vendor');

if (hasTotal)
  detectedFields.push('total');

if (hasDate)
  detectedFields.push('date');

if (hasBillingInformation)
  detectedFields.push('billingInformation');


// --------------------------------------------------
// Determine whether extraction looks like an invoice
// --------------------------------------------------

// Minimum requirement:
// At least TWO strong invoice indicators.
//
// Invoice number + total
// Invoice number + vendor
// Vendor + total
// etc.

const invoiceSignalCount =
  detectedFields.length;

const isInvoice =
  invoiceSignalCount >= 2;


// --------------------------------------------------
// Determine whether extraction itself worked
// --------------------------------------------------

const extractionSuccessful =
  text.length > 0;


// --------------------------------------------------
// Final validation
// --------------------------------------------------

const validInvoiceExtraction =
  extractionSuccessful &&
  isInvoice;


// --------------------------------------------------
// Return result
// --------------------------------------------------

return [
  {
    json: {
      ...$json,

      extractionSuccessful,

      isInvoice,

      validInvoiceExtraction,

      extractedTextLength: text.length,

      invoiceSignalCount,

      detectedInvoiceFields: detectedFields,

      validationStatus:
        validInvoiceExtraction
          ? 'valid_invoice'
          : extractionSuccessful
            ? 'not_invoice_or_insufficient_invoice_data'
            : 'extraction_failed'
    }
  }
];

const items = $input.all();

if (items.length === 0) {
  return [];
}

// GROUP ITEMS BY ATTACHMENT

const groups = {};

for (const item of items) {

  const data = item.json || {};

  const attachmentId =
    data.attachmentId ||
    data.attachmentKey ||
    data.fileName ||
    'unknown_attachment';

  if (!groups[attachmentId]) {
    groups[attachmentId] = [];
  }

  groups[attachmentId].push(item);
}


// =====================================================
// NORMALIZE EACH ATTACHMENT
// =====================================================

const output = [];

for (const [attachmentId, groupItems] of Object.entries(groups)) {

  let fileName = null;
  let mimeType = null;
  let fileType = null;
  let binary = null;

  const rows = [];


  // ===================================================
  // COLLECT METADATA
  // ===================================================

  for (const item of groupItems) {

    const data = item.json || {};

    fileName =
      fileName ||
      data.fileName ||
      data.filename ||
      null;

    mimeType =
      mimeType ||
      data.mimeType ||
      data.mimetype ||
      null;

    fileType =
      fileType ||
      data.fileType ||
      null;


    // Preserve binary if available
    if (!binary && item.binary) {
      binary = item.binary;
    }


    rows.push(data);
  }


  // ===================================================
  // DETERMINE FILE TYPE
  // ===================================================

  if (!fileType || fileType === 'unknown') {

    if (mimeType === 'application/pdf') {

      fileType = 'pdf';

    }

    else if (
      mimeType === 'application/msword' ||
      mimeType ===
        'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
    ) {

      fileType = 'word';

    }

    else if (
      mimeType === 'application/vnd.ms-excel' ||
      mimeType ===
        'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' ||
      mimeType === 'text/csv'
    ) {

      fileType = 'excel';

    }

    else if (
      typeof mimeType === 'string' &&
      mimeType.startsWith('image/')
    ) {

      fileType = 'image';

    }

    else if (mimeType === 'text/plain') {

      fileType = 'text';

    }

    else {

      fileType = 'unknown';

    }
  }


  // ===================================================
  // EXTRACT TEXT
  // ===================================================

  let extractedText = '';


  // ===================================================
  // IMAGE
  // ===================================================

  if (fileType === 'image') {

    extractedText = '';

  }


  // ===================================================
  // EXCEL
  // ===================================================

  else if (fileType === 'excel') {

    const metadataFields = [
      'attachmentId',
      'attachmentKey',
      'fileName',
      'filename',
      'mimeType',
      'mimetype',
      'fileType',
      'extractedText',
      'extractionSuccessful',
      'needsOCR',
      'extractionMethod'
    ];


    extractedText = rows
      .map(row => {

        return Object.entries(row)
          .filter(([key, value]) => {

            return (
              !metadataFields.includes(key) &&
              value !== null &&
              value !== undefined &&
              value !== ''
            );

          })
          .map(([key, value]) => {

            return String(value);

          })
          .join(' | ');

      })
      .filter(text => text.trim() !== '')
      .join('\n');

  }


  // ===================================================
  // PDF / WORD / TEXT
  // ===================================================

  else {

    const textParts = [];

    for (const item of groupItems) {

      const data = item.json || {};

      const possibleText =
        data.extractedText ||
        data.text ||
        data.content ||
        '';


      if (typeof possibleText === 'string') {

        const trimmed =
          possibleText.trim();

        if (trimmed) {
          textParts.push(trimmed);
        }

      }

    }

    extractedText =
      textParts.join('\n');

  }


  // ===================================================
  // OCR
  // ===================================================

  const needsOCR =
    fileType === 'image';


  // ===================================================
  // EXTRACTION SUCCESS
  // ===================================================

  const extractionSuccessful =
    !needsOCR &&
    extractedText.trim().length > 0;


  // ===================================================
  // EXTRACTION METHOD
  // ===================================================

  const extractionMethod =
    needsOCR
      ? 'pending_ocr'
      : fileType;


  // ===================================================
  // STANDARDIZED OUTPUT
  // ===================================================

  const normalizedItem = {

    json: {

      attachmentId,

      fileName,

      mimeType,

      fileType,

      extractedText,

      extractionSuccessful,

      needsOCR,

      extractionMethod,

      originalItemCount:
        groupItems.length

    }

  };


  // Preserve binary
  if (binary) {
    normalizedItem.binary = binary;
  }


  output.push(normalizedItem);

}


return output;

const items = $input.all();

const output = [];

for (const item of items) {

  const response = item.json || {};

  // =====================================================
  // GET CLAUDE TEXT RESPONSE
  // =====================================================

  let rawText =
    response.content?.[0]?.text || '';

  if (typeof rawText !== 'string') {
    rawText = '';
  }

  rawText = rawText.trim();


  // =====================================================
  // REMOVE MARKDOWN CODE FENCES
  // =====================================================

  rawText = rawText
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();


  // =====================================================
  // PARSE CLAUDE JSON
  // =====================================================

  let ocrData = {};

  try {

    ocrData = JSON.parse(rawText);

  } catch (error) {

    // If Claude returned invalid JSON,
    // keep the raw response so it can be inspected.

    ocrData = {
      extractedText: rawText
    };
  }


  // =====================================================
  // GET VALUES
  // =====================================================

  const attachmentId =
    ocrData.attachmentId ||
    null;

  const fileName =
    ocrData.fileName ||
    null;

  const mimeType =
    ocrData.mimeType ||
    null;

  const fileType =
    ocrData.fileType ||
    'image';

  const extractedText =
    typeof ocrData.extractedText === 'string'
      ? ocrData.extractedText.trim()
      : '';


  // =====================================================
  // STANDARDIZED OUTPUT
  // =====================================================

  output.push({

    json: {

      attachmentId,

      fileName,

      mimeType,

      fileType,

      extractedText,

      extractionSuccessful:
        extractedText.length > 0,

      needsOCR: false,

      extractionMethod:
        'claude_vision_ocr'

    },

    binary: item.binary

  });

}


return output;

const items = $input.all();

const invoiceKeywords = [
  'invoice',
  'invoice number',
  'invoice no',
  'invoice #',
  'total',
  'total due',
  'amount due',
  'vendor',
  'bill to',
  'subtotal',
  'tax',
  'vat',
  'date'
];

return items.map(item => {

  const data = item.json || {};

  const text =
    (data.extractedText || '')
      .trim();

  const lowerText =
    text.toLowerCase();


  // =====================================================
  // CHECK FOR INVOICE SIGNALS
  // =====================================================

  const keywordMatches =
    invoiceKeywords.filter(keyword =>
      lowerText.includes(keyword)
    );


  // =====================================================
  // CHECK WHETHER ENOUGH TEXT WAS EXTRACTED
  // =====================================================

  const hasEnoughText =
    text.length >= 50;


  // At least 2 invoice-related signals
  const hasInvoiceSignals =
    keywordMatches.length >= 2;


  // =====================================================
  // DETERMINE EXTRACTION QUALITY
  // =====================================================

  const extractionLooksUseful =
    hasEnoughText &&
    hasInvoiceSignals;


  // =====================================================
  // DETERMINE WHETHER OCR IS REQUIRED
  // =====================================================

  let needsOCR = false;

  // Images always need OCR
  if (data.fileType === 'image') {

    needsOCR = true;

  }

  // PDFs may be scanned/image-based or poorly extracted
  else if (data.fileType === 'pdf') {

    needsOCR =
      !extractionLooksUseful;

  }

  // Word documents with failed extraction
  else if (data.fileType === 'word') {

    needsOCR =
      !extractionLooksUseful;

  }

  // Text files with no useful extraction
  else if (data.fileType === 'text') {

    needsOCR =
      !extractionLooksUseful;

  }

  // Excel usually does not need OCR
  else if (data.fileType === 'excel') {

    needsOCR = false;

  }


  // =====================================================
  // RETURN UPDATED ITEM
  // =====================================================

  return {

    json: {

      ...data,

      extractionTextLength:
        text.length,

      invoiceKeywordMatches:
        keywordMatches,

      extractionLooksUseful,

      needsOCR,

      extractionSuccessful:
        extractionLooksUseful

    },

    binary:
      item.binary

  };

});
